USE ecommerce_analytics;
WITH product_profit AS (SELECT p.Product_ID,p.Product_Name,p.Category,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)-o.Quantity*p.Cost_Price-COALESCE(o.Shipping_Cost,0)) Profit FROM Orders o JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY p.Product_ID,p.Product_Name,p.Category) SELECT *,RANK() OVER(PARTITION BY Category ORDER BY Profit DESC) Category_Profit_Rank FROM product_profit;
WITH customer_revenue AS (SELECT c.Customer_ID,c.Customer_Name,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Revenue FROM Orders o JOIN Customers c ON o.Customer_ID=c.Customer_ID JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY c.Customer_ID,c.Customer_Name) SELECT *,DENSE_RANK() OVER(ORDER BY Revenue DESC) Revenue_Rank FROM customer_revenue;
WITH customer_metrics AS (SELECT c.Customer_ID,c.Customer_Name,MAX(o.Order_Date) Last_Order_Date,COUNT(DISTINCT o.Order_ID) Frequency,SUM(o.Quantity*p.Selling_Price*(1-o.Discount)) Monetary FROM Customers c LEFT JOIN Orders o ON c.Customer_ID=o.Customer_ID LEFT JOIN Products p ON o.Product_ID=p.Product_ID WHERE LOWER(TRIM(o.Order_Status))<>'cancelled' GROUP BY c.Customer_ID,c.Customer_Name) SELECT *,DATEDIFF((SELECT MAX(Order_Date) FROM Orders),Last_Order_Date) Recency_Days,NTILE(5) OVER(ORDER BY DATEDIFF((SELECT MAX(Order_Date) FROM Orders),Last_Order_Date) DESC) Recency_Score,NTILE(5) OVER(ORDER BY Frequency) Frequency_Score,NTILE(5) OVER(ORDER BY Monetary) Monetary_Score FROM customer_metrics WHERE Last_Order_Date IS NOT NULL;